<script setup>
import { onMounted, reactive, ref } from 'vue'
import {useAppliedQuery} from './analysisQuery.js'
import {percentText,intakeText,goalText,ratioText,bucketDays,completenessText,statusText} from './metricPresentation.js'
import { getNutrition } from '../../api/nutrition.js'
import DailyGoalsDialog from './DailyGoalsDialog.vue'
import NutritionTrendChart from './NutritionTrendChart.vue'
const props=defineProps({timeZone:{type:String,required:true}})
const today=new Intl.DateTimeFormat('en-CA',{timeZone:props.timeZone,year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date())
const filters=reactive({date_from:today.slice(0,8)+'01',date_to:today,group_by:'day'})
const data=ref(null),loading=ref(false),error=ref(''),code=ref(''),success=ref(''),metric=ref('calories_kcal'),goalsDialog=ref(null)
const fields=[['calories_kcal','热量','kcal'],['protein_g','蛋白质','g'],['fat_g','脂肪','g'],['carbohydrate_g','碳水化合物','g']]
const labels=statusText
const query=useAppliedQuery(filters), changed=query.changed, applied=query.applied
const groups={day:'按日',week:'按周',month:'按月'}
const format=v=>v==null?'—':new Intl.NumberFormat('zh-CN',{maximumFractionDigits:2}).format(v)
let version=0
async function load(){
  if(!filters.date_from||!filters.date_to||filters.date_from>filters.date_to){error.value='请输入正确的日期范围';return}
  const conditions=query.capture(),token=++version;loading.value=true;error.value='';code.value=''
  try{const response=await getNutrition(conditions);if(token===version){data.value=response;query.accept(conditions)}}
  catch(err){if(token===version){error.value=err.message;code.value=err.code}}
  finally{if(token===version)loading.value=false}
}
function saved(){success.value='营养目标已保存';load()}
onMounted(load)
</script>
<template><section class="analysis"><div class="heading"><div><h2>营养摄入分析</h2><p>后端统一统计已录入饮食，不作健康或医学判断。</p></div><button class="button primary" :disabled="loading||!!error" @click="goalsDialog.open()">设置每日目标</button></div>
  <form class="panel filters" @submit.prevent="load"><label>统计开始日期<input type="date" required v-model="filters.date_from" :disabled="loading" /></label><label>统计结束日期<input type="date" required v-model="filters.date_to" :disabled="loading" /></label><label>统计周期<select v-model="filters.group_by" :disabled="loading"><option value="day">按日</option><option value="week">按周（周一开始）</option><option value="month">按月</option></select></label><button class="button primary" :disabled="loading">查询统计</button></form>
  <p v-if="success" role="status" class="notice">{{ success }}</p><p v-if="loading" role="status">正在统计…</p><div v-if="error" role="alert" class="notice error">{{ error }} <RouterLink v-if="code==='PROFILE_REQUIRED'" to="/profile">前往建立档案</RouterLink><button class="button secondary" @click="load">重试</button></div>
  <p v-if="changed" class="notice" role="status">查询条件已变更，请点击查询。</p>
  <template v-if="data"><p v-if="changed" class="notice">以下数据对应上次查询条件：{{applied.date_from}} 至 {{applied.date_to}} · {{groups[applied.group_by]}}。</p><p class="note">{{ data.date_from }} 至 {{ data.date_to }} · {{ data.total.record_count }} 条记录 · {{ data.total.missing_days }} 天无记录。无记录不代表摄入为零。</p><p v-if="data.total.example_record_count" class="notice">包含 {{ data.total.example_record_count }} 条示例记录，统计含演示数值。</p>
    <div class="cards"><article class="panel" v-for="[key,label,unit] in fields" :key="key"><h3>{{ label }}已知摄入</h3><strong>{{ intakeText(data.total.nutrients[key],unit,bucketDays(data.total)) }}</strong><p>{{ completenessText(data.total.nutrients[key],bucketDays(data.total)) }}</p><p>已知 {{ data.total.nutrients[key].known_count }} 条 · 未知 {{ data.total.nutrients[key].unknown_count }} 条</p><p>范围目标：{{ goalText(data.total.nutrients[key],unit,bucketDays(data.total)) }}</p><p v-if="data.total.nutrients[key].target_missing_days">{{ data.total.nutrients[key].target_missing_days }} 天未设置目标，暂不计算达成率。</p><template v-if="data.total.nutrients[key].achievement_percent!==null"><p>{{ data.total.nutrients[key].ratio_basis==='known_only'?'已知部分对应比例':'目标达成率' }}：{{ percentText(data.total.nutrients[key].achievement_percent) }}</p><progress :value="Math.min(100,data.total.nutrients[key].achievement_percent)" max="100" :aria-label="label+'目标进度'" /></template><p v-else>目标达成率：{{ ratioText(data.total.nutrients[key],bucketDays(data.total)) }}</p></article></div>
    <div class="panel trend"><div class="heading"><h3>每日营养趋势</h3><label>趋势指标<select v-model="metric"><option v-for="[key,label] in fields" :key="key" :value="key">{{ label }}</option></select></label></div><p class="note">趋势图始终展示所选范围的每日数据，不随日、周、月汇总分组切换而改变。</p><NutritionTrendChart :daily="data.daily" :metric="metric" :label="fields.find(f=>f[0]===metric)[1]" :unit="fields.find(f=>f[0]===metric)[2]" /></div>
    <div class="panel table-wrap"><h3>周期统计明细</h3><table class="desktop-detail"><thead><tr><th>实际统计范围</th><th>记录</th><th v-for="[,label,unit] in fields" :key="label">{{ label }}（{{ unit }}）</th></tr></thead><tbody><tr v-for="item in data.items" :key="item.period_from"><th>{{ item.actual_from }}<br/>至 {{ item.actual_to }}<small v-if="item.is_partial_period">非完整自然周期</small></th><td>{{ item.record_count }} 条<br/>{{ item.missing_days }} 天无记录</td><td v-for="[key,,unit] in fields" :key="key">{{ intakeText(item.nutrients[key],unit,bucketDays(item)) }}<small>{{ completenessText(item.nutrients[key],bucketDays(item)) }}</small><small>目标 {{ goalText(item.nutrients[key],unit,bucketDays(item)) }}；比例 {{ ratioText(item.nutrients[key],bucketDays(item)) }}</small></td></tr></tbody></table><div class="mobile-detail"><article v-for="item in data.items" :key="item.period_from" class="detail-card"><h4>{{item.actual_from}} 至 {{item.actual_to}}</h4><p v-if="item.is_partial_period">非完整自然周期</p><p>{{item.record_count}} 条记录 · {{item.missing_days}} 天无记录</p><dl><div v-for="[key,label,unit] in fields" :key="key"><dt>{{label}}</dt><dd>{{intakeText(item.nutrients[key],unit,bucketDays(item))}}<small>{{completenessText(item.nutrients[key],bucketDays(item))}}</small><small>目标：{{goalText(item.nutrients[key],unit,bucketDays(item))}}</small><small>比例：{{ratioText(item.nutrients[key],bucketDays(item))}}</small></dd></div></dl></article></div></div>
    <details class="panel"><summary>查看趋势每日数值（{{ data.daily.length }}天）</summary><ul><li v-for="day in data.daily" :key="day.actual_from">{{ day.actual_from }}：{{ intakeText(day.nutrients[metric],fields.find(f=>f[0]===metric)[2]) }} · {{ labels[day.nutrients[metric].data_status] }}</li></ul></details><p class="note">{{ data.completeness_note }} 超过100%的比例照常显示，进度条最多填满。</p>
  </template><DailyGoalsDialog ref="goalsDialog" :time-zone="timeZone" @saved="saved" /></section></template>
<style scoped>.mobile-detail{display:none}.detail-card{border:1px solid #dfe8df;border-radius:10px;padding:14px;margin-top:12px;overflow-wrap:anywhere}.detail-card h4{font-size:14px}.detail-card p{font-size:13px;line-height:1.7;margin:8px 0}.detail-card dl{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.detail-card dt{font-size:13px;color:#64796d}.detail-card dd{font-size:14px;margin:6px 0}.detail-card small{display:block;font-size:12px;line-height:1.6;color:#64796d;margin-top:4px}@media(max-width:600px){.desktop-detail{display:none}.mobile-detail{display:block}}.heading{display:flex;justify-content:space-between;gap:16px;align-items:center;flex-wrap:wrap;margin-bottom:18px}.heading h2{font-size:23px}.heading p,.note{font-size:12px;color:#65796d;margin:10px 0;line-height:1.7}.panel{padding:22px;background:white;border:1px solid #e1e8de;border-radius:12px;margin-bottom:16px}.filters{display:flex;gap:12px;align-items:flex-end;flex-wrap:wrap}label{display:flex;flex-direction:column;gap:7px;font-size:13px}input,select{padding:10px;border:1px solid #cddace;border-radius:7px;font:inherit;color:inherit}.cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,220px),1fr));gap:14px}.cards h3{font-size:15px}.cards strong{display:block;font-size:26px;color:#246b58;margin:14px 0;overflow-wrap:anywhere}.cards small{font-size:12px}.cards p{font-size:12px;color:#65796d;margin:8px 0}progress{width:100%;accent-color:#246b58;height:12px}.notice{padding:14px;background:#edf5ef;border-radius:8px;margin:12px 0;font-size:13px}.error{color:#a04431;background:#fff0ec}.table-wrap{overflow-x:auto}table{border-collapse:collapse;width:100%;min-width:660px;font-size:12px}th,td{padding:12px;text-align:left;border-bottom:1px solid #e5ece7}td small,th small{display:block;color:#65796d;margin-top:5px}details li{font-size:12px;margin:8px 0}summary{cursor:pointer}@media(max-width:600px){.filters label{width:100%}.panel{padding:16px}.cards{grid-template-columns:1fr}}</style>
